tw.local.sqlStatements[j].sql = "update "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS set  ADVANCE_PAYMENT_OUTSTANDING_AMOUNT = ( (select min( AMOUNT_PAYABLE_BY_NBE) from "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS where ID= ?) - COALESCE((select sum(AMOUNT_ALLOCATED_FOR_REQUEST) from "+ tw.env.DBSchema +".IDC_ADVANCED_PAYMENT_USED where IDC_REQUEST_ID=? ),0)) where ID=?";

paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);
paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);
paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);
//-------------------------------------------Select-----------------------------------
i=0;
j++;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStatements[j].sql = "SELECT ADVANCE_PAYMENT_OUTSTANDING_AMOUNT FROM "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS WHERE ID=?;";

paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);

