scripts.script:
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();

tw.local.j = 0;
tw.local.i = 0;
function paramInit (value) {
//	tw.local.sqlStatements[tw.local.j].parameters = new tw.object.listOf.SQLParameter();
	tw.local.sqlStatements[tw.local.j].parameters[tw.local.i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[tw.local.j].parameters[tw.local.i].value = value;
	tw.local.i= tw.local.i+1;
}

if (tw.local.idcRequest.IDCRequestType.englishdescription == "Advance Payment") {
	tw.local.i=0;

	tw.local.sqlStatements[tw.local.j] = new tw.object.SQLStatement();
	tw.local.sqlStatements[tw.local.j].sql ="UPDATE "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS SET CUSTOMS_RELEASE_AMOUNT=CUSTOMS_RELEASE_AMOUNT+? WHERE "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS.REQUEST_NUMBER = ?;";
	tw.local.sqlStatements[tw.local.j].parameters = new tw.object.listOf.SQLParameter();
	paramInit (tw.local.idcRequest.releaseAmount);
	paramInit (tw.local.idcRequest.ParentIDCRequestNumber);
}else{

	if (tw.local.idcRequest.financialDetails.usedAdvancePayment.listLength>0) {
		for (tw.local.j=0; tw.local.j<tw.local.idcRequest.financialDetails.usedAdvancePayment.listLength; tw.local.j+=1) {
			tw.local.i=0;
			tw.local.sqlStatements[tw.local.j] = new tw.object.SQLStatement();
			tw.local.sqlStatements[tw.local.j].sql ="UPDATE "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS SET CUSTOMS_RELEASE_AMOUNT=CUSTOMS_RELEASE_AMOUNT+? WHERE "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS.id = ?;";
			tw.local.sqlStatements[tw.local.j].parameters = new tw.object.listOf.SQLParameter();
			paramInit (tw.local.idcRequest.financialDetails.usedAdvancePayment[tw.local.j].AmountAllocated);
			paramInit (tw.local.idcRequest.financialDetails.usedAdvancePayment[tw.local.j].DBID);
		}
	}
	tw.local.i=0;
	tw.local.sqlStatements[tw.local.j] = new tw.object.SQLStatement();
	tw.local.sqlStatements[tw.local.j].sql ="UPDATE "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS SET CUSTOMS_RELEASE_AMOUNT=? WHERE "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS.REQUEST_NUMBER = ?;";
	tw.local.sqlStatements[tw.local.j].parameters = new tw.object.listOf.SQLParameter();
	paramInit (tw.local.idcRequest.financialDetails.amtPayableByNBE);
	paramInit (tw.local.idcRequest.ParentIDCRequestNumber);
}

if (tw.local.error != undefined && !!tw.local.error.errorText) {
	tw.local.errorMSG = tw.local.error.errorText;
}else if (tw.system.error != undefined && tw.system.error != null) {
	tw.local.errorMSG = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
	tw.local.error = new tw.object.AjaxError();
}else{
