/**----------------------------------------------------NOTES-----------------------------------------------------------------------**/
// Advices is assumed and needs verification !!
// Accountee is skipped
// REMITTING BANK - DRAWER - CASE IN NEED - DRAWEE
// Interest details are not populated
/**---------------------------------------------------------------------------------------------------------------------------------**/
/**--------------------------------------------------------CONSTANTS----------------------------------------------------------------**/
// Party Types
const PARTY_TYPES = {
	REMITTING_BANK: "REMITTING BANK",
	DRAWER: "DRAWER",
	CASE_IN_NEED: "CASE IN NEED",
	DRAWEE: "DRAWEE",
	ACCOUNTEE: "ACCOUNTEE",
};

// Constants for Default Values
const DEFAULT_VALUES = {
	CREATE_SN: "1",
	YES: "Y",
	NO: "N",
	SWIFT: "SWIFT",
	IAVC: "IAVC",
	EDITABLE: "editable",
};

/**---------------------------------------------------------------------------------------------------------------------------------**/

tw.local.Contract_Details_Full = new tw.object.toolkit.NBEINTT.Contract_Details_Full_1();

tw.local.Contract_Details_Full.ProductCode = tw.local.IDCContract.IDCProduct.code;
tw.local.Contract_Details_Full.Currency = tw.local.IDCRequest.financialDetails.documentCurrency.code;
var idcStage = tw.local.IDCContract.IDCRequestStage;
var BillStage = idcStage == tw.epv.IDCstage.fiinal + "" ? tw.epv.IDCstage.fin + "" : tw.epv.IDCstage.ini + "";

tw.local.Contract_Details_Full.BillStage = BillStage;
tw.local.Contract_Details_Full.Amount = String(tw.local.IDCRequest.financialDetails.amtPayableByNBE);
tw.local.Contract_Details_Full.CCY = tw.local.IDCRequest.financialDetails.documentCurrency.code;
tw.local.Contract_Details_Full.OutstandingAmount = String(tw.local.IDCContract.outstandingAmount);
tw.local.Contract_Details_Full.MaturityDate = formatDate(tw.local.IDCContract.transactionMaturityDate);
tw.local.Contract_Details_Full.CustomerId = tw.local.IDCRequest.customerInformation.CIFNumber;
tw.local.Contract_Details_Full.PartyType = PARTY_TYPES.DRAWEE;
tw.local.Contract_Details_Full.BranchCode = tw.local.IDCRequest.financialDetails.executionHub.code;
tw.local.Contract_Details_Full.USEREFNO = tw.local.IDCContract.userReference;
tw.local.Contract_Details_Full.VALDT = formatDate(tw.local.IDCContract.transactionValueDate);
tw.local.Contract_Details_Full.TENOR_DAYS = tw.local.IDCContract.transactionTenorDays;
tw.local.Contract_Details_Full.TRANSITDAYS = tw.local.IDCContract.transactionTransitDays;
tw.local.Contract_Details_Full.BASDT = formatDate(tw.local.IDCContract.transactionBaseDate);
if (tw.local.IDCContract.interestVisibility.toLowerCase() == DEFAULT_VALUES.EDITABLE) {
	tw.local.Contract_Details_Full.FROMDATE = formatDate(tw.local.IDCContract.interestFromDate);
	tw.local.Contract_Details_Full.TODATE = formatDate(tw.local.IDCContract.interestToDate);
}

if (tw.local.IDCContract.collateralAmount > 0) {
	tw.local.Contract_Details_Full.CollateralAmount = String(tw.local.IDCContract.collateralAmount);
	tw.local.Contract_Details_Full.CollateralCurrency = tw.local.IDCContract.collateralCurrency.code;
}

tw.local.Contract_Details_Full.OPERATION = tw.local.IDCRequest.operationType.value;
if (tw.local.IDCContract.IDCProduct.code == DEFAULT_VALUES.IAVC) {
	tw.local.Contract_Details_Full.ACPFRMDT = tw.local.Contract_Details_Full.FROMDATE;
	tw.local.Contract_Details_Full.ACPTODT = tw.local.Contract_Details_Full.TODATE;
}

// tw.local.Contract_Details_Full.Maker = "";
// tw.local.Contract_Details_Full.Checker = "";
// tw.local.Contract_Details_Full.TransStatus = "";
// tw.local.Contract_Details_Full.AuthStatus = "";
// tw.local.Contract_Details_Full.LC_CUST = "";
// tw.local.Contract_Details_Full.LCREFNO = "";
// tw.local.Contract_Details_Full.USE_LC_REF_MESS = "";
//tw.local.Contract_Details_Full.VDATECR = tw.local.ContractDetails.ContractLiquidation.creditValueDate;
//tw.local.Contract_Details_Full.DRVALDT = tw.local.ContractDetails.ContractLiquidation.debitValueDate;
// tw.local.Contract_Details_Full.TXNDT = new TWDate();
// tw.local.Contract_Details_Full.TRANSFERCOLLATFROMLC = "";
// tw.local.Contract_Details_Full.TFR_COLL_AMT = 0.0;
// tw.local.Contract_Details_Full.LimitMonitoringFlag = "";
// tw.local.Contract_Details_Full.EXTREFNO = "";

/**---------------------------------------------Parties-------------------------------------------------------**/
tw.local.Contract_Details_Full.Contract_Parties = new tw.object.listOf.toolkit.NBEINTT.Contract_Parties_8();

if (tw.local.IDCContract.party && tw.local.IDCContract.party.length > 0) {
	for (var i = 0; i < tw.local.IDCContract.party.length; i++) {
		if (tw.local.IDCContract.party[i].partyType.value.toLowerCase() == PARTY_TYPES.ACCOUNTEE.toLowerCase()) continue;
		tw.local.Contract_Details_Full.Contract_Parties[i] = new tw.object.toolkit.NBEINTT.Contract_Parties_8();
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyLang = tw.local.IDCContract.party[i].language;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyCountryCode = tw.local.IDCContract.party[i].country;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyRefNum = tw.local.IDCContract.party[i].reference;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyName = tw.local.IDCContract.party[i].name.toUpperCase();
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress1 = tw.local.IDCContract.party[i].address1;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress2 = tw.local.IDCContract.party[i].address2;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress3 = tw.local.IDCContract.party[i].address3;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress4 = tw.local.IDCContract.party[i].address4;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyId = tw.local.IDCContract.party[i].partyId;
		tw.local.Contract_Details_Full.Contract_Parties[i].PartyType = tw.local.IDCContract.party[i].partyType.value.toUpperCase();

		if (tw.local.Contract_Details_Full.Contract_Parties[i].PartyType.trim().toLowerCase() == PARTY_TYPES.REMITTING_BANK.toLowerCase()) {
			tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress = new tw.object.listOf.toolkit.NBEINTT.PartyAddress();
			tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress[0] = new tw.object.toolkit.NBEINTT.PartyAddress();
			tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress[0].Media = tw.local.IDCContract.party[i].media;
			tw.local.Contract_Details_Full.Contract_Parties[i].PartyAddress[0].Address = tw.local.IDCContract.party[i].address;
		}
	}
}

/**---------------------------------------------TXNUDFDETAILS-------------------------------------------------------**/
/*
Administration_Fees
Customer_Resources
Free_Market
Goods_ARB_Description_CBE
Goods_Dsc_CBE
Good_Origin
INCO Terms
رقم موافقة وحدة تمويل التجارة
*/
tw.local.Contract_Details_Full.TXNUDFDETAILS = new tw.object.listOf.toolkit.NBEINTT.TXNUDFDETAILS_6();
addTXNUDFDETAILS(tw.epv.UDFs.Administration_Fees + "", tw.local.IDCContract.adminFees.value);
addTXNUDFDETAILS(tw.epv.UDFs.Customer_Resources + "", tw.local.IDCRequest.financialDetails.customerResources);
addTXNUDFDETAILS(tw.epv.UDFs.Free_Market + "", tw.local.IDCRequest.financialDetails.freeMarket || 0);
addTXNUDFDETAILS(tw.epv.UDFs.TradeFinanceUnitApprovalNumber + "", tw.local.IDCRequest.financialDetails.tradeFinanceApprovalNumber);
addTXNUDFDETAILS(tw.epv.UDFs.Goods_ARB_Description_CBE + "", tw.local.IDCRequest.commodityDescription);
addTXNUDFDETAILS(tw.epv.UDFs.Goods_Dsc_CBE + "", tw.local.IDCRequest.productsDetails.CBEGoods.value);
addTXNUDFDETAILS(tw.epv.UDFs.INCO_Terms + "", tw.local.IDCRequest.productsDetails.incoterms.code);
addTXNUDFDETAILS(tw.epv.UDFs.Good_Origin + "", tw.local.IDCRequest.countryOfOrigin.englishdescription);

/**---------------------------------------------Charges and Settlements-------------------------------------------------**/
tw.local.Contract_Details_Full.Settlements = new tw.object.toolkit.NBEINTT.Settlements_26();
tw.local.Contract_Details_Full.Settlements.Contract_Settlement = new tw.object.listOf.toolkit.NBEINTT.Contract_Settlement_21();
// tw.local.Contract_Details_Full.Settlements.LATEVNSEQNO = "";
if (tw.local.IDCContract.commissionsAndCharges && tw.local.IDCContract.commissionsAndCharges.length > 0) {
	tw.local.Contract_Details_Full.Charges = new tw.object.listOf.toolkit.NBEINTT.Charges_25();
	tw.local.Contract_Details_Full.Charges[0] = new tw.object.toolkit.NBEINTT.Charges_25();
	tw.local.Contract_Details_Full.Charges[0].Charge_Association = new tw.object.listOf.toolkit.NBEINTT.Charge_Association_18();
	tw.local.Contract_Details_Full.Charges[0].ChargeApplication = new tw.object.listOf.toolkit.NBEINTT.ChargeApplication_5();

	for (var i = 0; i < tw.local.IDCContract.commissionsAndCharges.length; i++) {
		// Charge_Association
		tw.local.Contract_Details_Full.Charges[0].Charge_Association[i] = new tw.object.toolkit.NBEINTT.Charge_Association_18();
		tw.local.Contract_Details_Full.Charges[0].Charge_Association[i].COMPNT = tw.local.IDCContract.commissionsAndCharges[i].component;
		tw.local.Contract_Details_Full.Charges[0].Charge_Association[i].CreateSn = DEFAULT_VALUES.CREATE_SN;
		// ChargeApplication
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i] = new tw.object.toolkit.NBEINTT.ChargeApplication_5();
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].COMPNT = tw.local.IDCContract.commissionsAndCharges[i].component;
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].CHRGAMT = String(tw.local.IDCContract.commissionsAndCharges[i].chargeAmount);
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].WAIVER = tw.local.IDCContract.commissionsAndCharges[i].waiver ? DEFAULT_VALUES.YES : DEFAULT_VALUES.NO;
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].CreateSn = DEFAULT_VALUES.CREATE_SN;
		// tw.local.Contract_Details_Full.Charges[0].ChargeApplication[0].TGCCY = "";
		//----------------------------------------------------------------------------------
		if (!tw.local.IDCContract.commissionsAndCharges[i].waiver && tw.local.IDCContract.commissionsAndCharges[i].debitedAccount && tw.local.IDCContract.commissionsAndCharges[i].debitedAmount) {
			var compnt = tw.local.IDCContract.commissionsAndCharges[i].component;
			var branch = tw.local.IDCContract.commissionsAndCharges[i].debitedAccount.accountBranchCode;
			var gl = tw.local.IDCContract.commissionsAndCharges[i].debitedAccount.GLAccountNumber;
			var acc = gl ? gl : tw.local.IDCContract.commissionsAndCharges[i].debitedAccount.accountNumber;
			var currency = tw.local.IDCContract.commissionsAndCharges[i].debitedAccount.accountCurrency.code;
			var exRate = String(tw.local.IDCContract.commissionsAndCharges[i].debitedAmount.standardExchangeRate);
			addContractSettlement(compnt, String(branch), String(acc), currency, exRate);
		}
	}
}

/**------------------------------------------------Collateral Details---------------------------------------------------**/

if (tw.local.IDCContract.collateralAmount > 0 && tw.local.IDCContract.cashCollateralAccounts && tw.local.IDCContract.cashCollateralAccounts.length > 0) {
	for (var i = 0; i < tw.local.IDCContract.cashCollateralAccounts.length; i++) {
		var branch = String(tw.local.IDCContract.cashCollateralAccounts[i].accountBranchCode);
		var gl = tw.local.IDCContract.cashCollateralAccounts[i].GLAccountNumber;
		var acc = gl || tw.local.IDCContract.cashCollateralAccounts[i].accountNumber.value;
		var currency = tw.local.IDCContract.cashCollateralAccounts[i].accountCurrency;
		var len = tw.local.Contract_Details_Full.Settlements.Contract_Settlement.length;
		addContractSettlement("", branch, acc, currency);
	}
}

/**------------------------------------------------Contract_Multitnr----------------------------------------------------**/
if (tw.local.IDCRequest.financialDetails.multiTenorDates.length > 0) {
	tw.local.Contract_Details_Full.ContractMultitnr = new tw.object.listOf.toolkit.NBEINTT.ContractMultitnr();
	for (var i = 0; i < tw.local.IDCRequest.financialDetails.multiTenorDates.length; i++) {
		tw.local.Contract_Details_Full.ContractMultitnr[i] = new tw.object.toolkit.NBEINTT.ContractMultitnr();
		tw.local.Contract_Details_Full.ContractMultitnr[i].SERIALNUM = i;
		tw.local.Contract_Details_Full.ContractMultitnr[i].BASDATE = formatDate(tw.local.IDCRequest.financialDetails.multiTenorDates[i].instalmentBaseDate);
		tw.local.Contract_Details_Full.ContractMultitnr[i].VALUDATE = tw.local.Contract_Details_Full.VALDT;
		tw.local.Contract_Details_Full.ContractMultitnr[i].TNOR = String(tw.local.IDCRequest.financialDetails.multiTenorDates[i].instalmentTenorDays);
		tw.local.Contract_Details_Full.ContractMultitnr[i].BILLAMNT = String(tw.local.IDCRequest.financialDetails.multiTenorDates[i].amount);
		//		tw.local.Contract_Details_Full.ContractMultitnr[i].TRANSTDAYS = String(tw.local.IDCContract.transactionTransitDays);
		// tw.local.Contract_Details_Full.ContractMultitnr[i].SPLITPCT = 0.0;
	}
}

/**--------------------------------------------------Advice-----------------------------------------------------------------**/

tw.local.Contract_Details_Full.Adice = new tw.object.toolkit.NBEINTT.Adice_1();
if (tw.local.IDCContract.advices && tw.local.IDCContract.advices.listLength > 0) {
	tw.local.Contract_Details_Full.Adice.ADV_CODE = tw.local.IDCContract.advices[0].messageType;
	tw.local.Contract_Details_Full.Adice.SUPRESS = tw.local.IDCContract.advices[0].suppressed ? DEFAULT_VALUES.YES : DEFAULT_VALUES.NO;
	tw.local.Contract_Details_Full.Adice.MEDIUM = DEFAULT_VALUES.SWIFT;
	tw.local.Contract_Details_Full.Adice.Fft = new tw.object.listOf.toolkit.NBEINTT.Fft_1();
	tw.local.Contract_Details_Full.Adice.Fft[0] = new tw.object.toolkit.NBEINTT.Fft_1();
	tw.local.Contract_Details_Full.Adice.Fft[0].FFT_CODE = tw.local.IDCContract.advices[0].adviceCode;
	// combine all advicelines into one txt
	var combinedText = tw.local.IDCContract.advices[0].advicelines.propertyValues.join(" ").trim();
	tw.local.Contract_Details_Full.Adice.Fft[0].FFTTXT = combinedText;
	// tw.local.Contract_Details_Full.Adice.Ins = new tw.object.listOf.toolkit.NBEINTT.Ins_2();
	// tw.local.Contract_Details_Full.Adice.Ins[0] = new tw.object.toolkit.NBEINTT.Ins_2();
	// tw.local.Contract_Details_Full.Adice.Ins[0].INSCD = "";
	// tw.local.Contract_Details_Full.Adice.Ins[0].INSTXT = "";
}

/**-----------------------------------------------------------------------------------------------------------------------------------------**/

//Interest
// tw.local.Contract_Details_Full.Intrest = new tw.object.listOf.toolkit.NBEINTT.IntrestDetails();
// tw.local.Contract_Details_Full.Intrest[0] = new tw.object.toolkit.NBEINTT.IntrestDetails();

// ContractGoodsDetails
// tw.local.Contract_Details_Full.ContractGoodsDetails = new tw.object.listOf.toolkit.NBEINTT.ContractGoodsDetails();
// tw.local.Contract_Details_Full.ContractGoodsDetails[0] = new tw.object.toolkit.NBEINTT.ContractGoodsDetails();

//Party_Limits
// tw.local.Contract_Details_Full.Party_Limits = new tw.object.listOf.toolkit.NBEINTT.Party_Limits_4();
// Document_Details
// tw.local.Contract_Details_Full.Document_Details = new tw.object.listOf.toolkit.NBEINTT.Document_Details_9();
//Goods
