function addTXNUDFDETAILS(fieldName, fieldValue) {
	var detail = new tw.object.toolkit.NBEINTT.TXNUDFDETAILS_6();
	var len = tw.local.Contract_Details_Full.TXNUDFDETAILS.listLength;
	detail.FLDNAME = String(fieldName);
	detail.FLDVAL = String(fieldValue) || "";
	tw.local.Contract_Details_Full.TXNUDFDETAILS.insertIntoList(len, detail);
}

// Function to add Contract Settlement
function addContractSettlement(component, accountBranchCode, accountNumber, accountCurrency, exchangeRate) {
	var settlement = new tw.object.toolkit.NBEINTT.Contract_Settlement_21();
	settlement.COMPNT = component;
	settlement.ACCBRN = accountBranchCode;
	settlement.ACC = accountNumber;
	settlement.ACCCCY = accountCurrency;
	if (exchangeRate) settlement.EXRATE = String(exchangeRate);
	// settlement.TAGCCY = "";

	var len = tw.local.Contract_Details_Full.Settlements.Contract_Settlement.listLength;
	tw.local.Contract_Details_Full.Settlements.Contract_Settlement.insertIntoList(len, settlement);
}

