tw.local.sql = "SELECT REQUEST_TYPE_ID, ENGLISH_DESCRIPTION FROM "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS d join "+ tw.env.DBSchema +".IDC_REQUEST_TYPE r on d.REQUEST_TYPE_ID = r.ID WHERE REQUEST_NUMBER = ?";

tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
tw.local.sqlStatements[0] = new tw.object.SQLStatement();
tw.local.sqlStatements[0].sql = tw.local.sql;
tw.local.sqlStatements[0].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStatements[0].parameters[0] = new tw.object.SQLParameter();
tw.local.sqlStatements[0].parameters[0].value = tw.local.idcRequest.ParentIDCRequestNumber;

tw.local.sqlStatements[1] = new tw.object.SQLStatement();
tw.local.sqlStatements[1].sql = "SELECT t.ENGLISH_DESCRIPTION, n.ENGLISH_DESCRIPTION FROM  "+ tw.env.DBSchema +".IDC_REQUEST_TYPE t , "+ tw.env.DBSchema +".IDC_REQUEST_NATURE n WHERE t.ID = ? AND n.ID = ?";
tw.local.sqlStatements[1].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStatements[1].parameters[0] = new tw.object.SQLParameter();
tw.local.sqlStatements[1].parameters[0].value = tw.local.idcRequest.IDCRequestType.id;

tw.local.sqlStatements[1].parameters[1] = new tw.object.SQLParameter();
tw.local.sqlStatements[1].parameters[1].value = tw.local.idcRequest.IDCRequestNature.id;

tw.local.isfound = true;
if (tw.local.results[0].rows.listLength == 0) {
	tw.local.isfound = false;
	tw.local.message = "The Parent Request Number is not exist";
}else{
	tw.local.parentType = {};
	tw.local.parentType.id = tw.local.results[0].rows[0].data[0];
	tw.local.parentType.englishdescription = tw.local.results[0].rows[0].data[1];
	
	tw.local.idcRequest.IDCRequestType.englishdescription = tw.local.results[1].rows[0].data[0];
	tw.local.idcRequest.IDCRequestNature.englishdescription = tw.local.results[1].rows[0].data[1];
}

if (tw.local.error != null && !!tw.local.error.errorText) {
	tw.local.errorMSG = tw.local.error.errorText;
}else if ( tw.system.error != null) {
	tw.local.errorMSG = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
	tw.local.error = new tw.object.AjaxError();
}else{
	tw.local.error = new tw.object.AjaxError();
}

tw.local.error.errorText = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name+"<br> Error Message : "+tw.local.errorMSG;
log.error("IDC PROCESS with ID "+tw.system.currentProcessInstanceID+" An Error Occured in Service Name : "+tw.system.serviceFlow.name+" with Error Message : "+tw.local.errorMSG);

if (tw.local.error != null && !!tw.local.error.errorText) {
	tw.local.errorMSG = tw.local.error.errorText;
}else if ( tw.system.error != null) {
	tw.local.errorMSG = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
	tw.local.error = new tw.object.AjaxError();
}else{
	tw.local.error = new tw.object.AjaxError();
}

tw.local.error.errorText = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name+"<br> Error Message : "+tw.local.errorMSG;
log.error("IDC PROCESS with ID "+tw.system.currentProcessInstanceID+" An Error Occured in Service Name : "+tw.system.serviceFlow.name+" with Error Message : "+tw.local.errorMSG);

if(tw.local.sqlResults != null && tw.local.sqlResults.listLength != 0)
{
	tw.local.hubName = tw.local.sqlResults[0].rows[0].data[0];
}

tw.local.sqlQuery = "select ARABIC_DESCRIPTION from "+ tw.env.DBSchema +".IDC_Execution_Hubs where code = ?";
tw.local.parameters = new tw.object.listOf.SQLParameter();
tw.local.parameters[0] = new tw.object.SQLParameter();
tw.local.parameters[0].type = "VARCHAR";
tw.local.parameters[0].value = tw.local.data;

// actionsTypes : step - recall - approve
if( tw.local.data && tw.local.data != "" ){
	var inputs = tw.local.data.split("&");
	tw.local.taskId = inputs[0] || "";
	tw.local.actionsType = inputs[1] || "step";
	tw.local.lastAction = inputs[2];
	tw.local.requestNature = inputs[3] || "";
	tw.local.requestNum = inputs[4] || "";
	tw.local.requestType = inputs[5] || "";
	
	tw.local.stepName = String(tw.system.findTaskByID(tw.local.taskId).processActivityName);
	
	log.info("IDC GET ACTIONS SERVICE INPUTS: ", tw.local.data)
}

var actions = [];
actions = [tw.epv.Action.obtainApprovals + ""];

// map actions
tw.local.results = new tw.object.listOf.String();
tw.local.results = actions;

var stepName = tw.local.stepName || "";

var initiatorList = [tw.epv.ActivityNames.createIdc + "", tw.epv.ActivityNames.createIdcHubReturn+""];
var makerList = [tw.epv.ActivityNames.tradeFo + "", tw.epv.ActivityNames.hubInit + "", tw.epv.ActivityNames.hubLiq + ""];
var checkerList = [tw.epv.ActivityNames.branchComp + ""];
var checkerListHub = [tw.epv.ActivityNames.hubInitReview + "", tw.epv.ActivityNames.hubLiqReview + ""];
var approvalsList = [tw.epv.ActivityNames.tradeComp + "", tw.epv.ActivityNames.cadMaker + "", tw.epv.ActivityNames.cadChecker + "", tw.epv.ActivityNames.cadPending + "", tw.epv.ActivityNames.treasMaker + "", tw.epv.ActivityNames.treasChecker + "", tw.epv.ActivityNames.cbeWaiting + ""];
var actions = [];

// if stepName is in makerList, actions will be : terminateRequest
// if stepName is in checkerList, actions will be : returnToMaker
// if stepName is in approvals, actions will be : returnToInitiator

if (initiatorList.indexOf(stepName) > -1) {
	actions = [tw.epv.Action.cancelReques + ""];
}

else if (makerList.indexOf(stepName) > -1) {
	actions = [tw.epv.Action.terminateRequest + ""];
}

else if (checkerListHub.indexOf(stepName) > -1) {
      actions = [tw.epv.Action.returnToMaker + "", tw.epv.Action.terminateRequest + ""];
      
} else if (checkerList.indexOf(stepName) > -1) {
      actions = [tw.epv.Action.returnToMaker + ""];
      
} else if (approvalsList.indexOf(stepName) > -1) {
	actions = [tw.epv.Action.returnToInitiator + ""];
}

// map actions
tw.local.results = new tw.object.listOf.String();
tw.local.results = actions;

var lastAction = tw.local.lastAction || "";
var requestNature = tw.local.requestNature || "";
var stepName = tw.local.stepName;
var requestType = tw.local.requestType;
var isHub = tw.local.isHub;
//var stepName = "IDC Execution Hub – Liquidation Review";
//tw.local.errorMsg = stepName;
//tw.local.actionsType = tw.epv.ActivityNames.hubLiqReview;
//tw.local.isExist = stepName === tw.epv.ActivityNames.hubLiqReview+"";

var actions = [];

switch (stepName) {
	case tw.epv.ActivityNames.createIdc + "":
		actions = [tw.epv.Action.submitRequest + "", tw.epv.Action.cancelReques + ""];
		// add submitRequestToHubDirectly
		if(isHub && (requestType ==tw.epv.IDCRequestTypes.idcAmendment+"" || requestType == tw.epv.IDCRequestTypes.idcPayment+"")){
			actions.push(tw.epv.Action.submitRequestToHubDirectly + "");
		}
		break;
	
	case tw.epv.ActivityNames.createIdcHubReturn + "":
		actions = [tw.epv.Action.submitRequest + "", tw.epv.Action.cancelReques + ""];
		// add submitRequestToHubDirectly
		if(isHub && (requestType ==tw.epv.IDCRequestTypes.idcAmendment+"" || requestType == tw.epv.IDCRequestTypes.idcPayment+"")){
			actions.push(tw.epv.Action.submitRequestToHubDirectly + "");
		}
		break;
	
	case tw.epv.ActivityNames.branchComp + "":
		actions = [tw.epv.Action.submitRequest + "", tw.epv.Action.returnToInitiator + "", tw.epv.Action.obtainCompApproval + ""];
		break;

	case tw.epv.ActivityNames.tradeFo + "":
		actions = [tw.epv.Action.approveRequest + "", tw.epv.Action.returnToInitiator + "", tw.epv.Action.terminateRequest + ""];
		break;

	case tw.epv.ActivityNames.tradeComp + "":
		actions = [tw.epv.Action.returnToInitiator + "", tw.epv.Action.approveRequest + ""];
		break;

	case tw.epv.ActivityNames.cadMaker + "":
		actions = [tw.epv.Action.returnToInitiator + "", tw.epv.Action.SendtoCheckerforApproval + "", tw.epv.Action.SendtoInvestigation + ""];
		break;

	case tw.epv.ActivityNames.cadChecker + "":
		actions = [tw.epv.Action.returnToMaker + "", tw.epv.Action.SendtoInvestigation + "", tw.epv.Action.returnToInitiator + "", tw.epv.Action.approveRequest + "", tw.epv.Action.ApproveMakerDecision + ""];
		break;

	case tw.epv.ActivityNames.cadPending + "":
		actions = [tw.epv.Action.sendBackToCADExecutionMakerPool + ""];
		break;

	case tw.epv.ActivityNames.treasMaker + "":
		actions = [tw.epv.Action.returnToInitiator + "", tw.epv.Action.SendtoCheckerforApproval + "", tw.epv.Action.sendCBEPending + ""];
		break;

	case tw.epv.ActivityNames.treasChecker + "":
		actions = [tw.epv.Action.approveRequest + "", tw.epv.Action.returnToMaker + ""];
		break;

	case tw.epv.ActivityNames.cbeWaiting + "":
		actions = [tw.epv.Action.sendBackToMainQueue + ""];
		break;

	case tw.epv.ActivityNames.hubInit + "":
		actions = [];

		if (requestNature == "2") {
			actions.push(tw.epv.Action.amendContract + "");
		} else {
			actions.push(tw.epv.Action.createContract + "");
		}

		if (lastAction == tw.epv.Action.submitRequestToHubDirectly + "") {
			actions.push(tw.epv.Action.returnToInitiator + "");
		} else {
			actions.push(tw.epv.Action.returnToTradeFO + "");
		}

		actions.push(tw.epv.Action.terminateRequest + "");
		// actions.push(tw.epv.Action.obtainApprovals + "");
		break;

	case tw.epv.ActivityNames.hubLiq + "":
		actions = [tw.epv.Action.returnToTradeFO + "", tw.epv.Action.terminateRequest + "", tw.epv.Action.createLiquidation + ""];
		// actions.push(tw.epv.Action.obtainApprovals + "");
		break;

	case tw.epv.ActivityNames.hubInitReview + "":
		actions = [tw.epv.Action.returnToMaker + ""];
            if (lastAction == tw.epv.Action.createContract + "" || lastAction == tw.epv.Action.amendContract + "") {
                  actions.push(tw.epv.Action.authorize + "");
            } else if (lastAction == tw.epv.Action.obtainApprovals + "") {
                  actions.push(tw.epv.Action.obtainApprovals + "");
            } else if (lastAction == tw.epv.Action.returnToTradeFO + "") {
                  actions.push(tw.epv.Action.returnToTradeFO + "");
            } else if (lastAction == tw.epv.Action.returnToInitiator + "") {
                  actions.push(tw.epv.Action.returnToInitiator + "");
            } else if (lastAction == tw.epv.Action.terminateRequest) {
                  actions.push(tw.epv.Action.terminateRequest + "");
            } else if (lastAction == tw.epv.Action.authorize + "") {
			actions.push(tw.epv.Action.authorizeICAPClosure+"");
		}
		break;

	case tw.epv.ActivityNames.hubLiqReview + "":
		actions = [tw.epv.Action.returnToMaker + ""];
		//		if (lastAction == tw.epv.Action.submitLiquidation + "") {
		if (lastAction == tw.epv.Action.createLiquidation + "") {
			actions.push(tw.epv.Action.authorize + "");
		}
		if (lastAction == tw.epv.Action.obtainApprovals + "") {
			actions.push(tw.epv.Action.obtainApprovals + "");
		} else if (lastAction == tw.epv.Action.returnToTradeFO) {
			actions.push(tw.epv.Action.returnToTradeFO + "");
		} else if (lastAction == tw.epv.Action.terminateRequest) {
			actions.push(tw.epv.Action.terminateRequest + "");
		}
		break;

	case tw.epv.ActivityNames.printDocs + "":
		actions = [tw.epv.Action.completeRequest + ""];
		break;

	default:
		//		actions = ["test1", "test2"];
		log.info("Get IDC Actions List Error: ", "No actions found for step: " + stepName, "Request Nature: " + requestNature, "Last Action: " + lastAction);
		break;
}
// map actions
tw.local.results = new tw.object.listOf.String();
tw.local.results = actions;

if (!tw.local.error) tw.local.error = new tw.object.AjaxError();

if(tw.system.error)
	tw.local.error.errorText = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
else 
	tw.local.error.errorText = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name

