scripts.script:
if (tw.local.error != null && !!tw.local.error.errorText) {
	tw.local.errorMSG = tw.local.error.errorText;
}else if ( tw.system.error != null) {
	tw.local.errorMSG = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
	tw.local.error = new tw.object.AjaxError();
}else{
	tw.local.error = new tw.object.AjaxError();
}

tw.local.error.errorText = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name+"<br> Error Message : "+tw.local.errorMSG;
log.error("IDC PROCESS with ID "+tw.system.currentProcessInstanceID+" An Error Occured in Service Name : "+tw.system.serviceFlow.name+" with Error Message : "+tw.local.errorMSG);

tw.local.cifs = [];
tw.local.partyType = [];
for (var i=0; i<tw.local.idcContract.party.length; i++) {
	if (tw.local.idcContract.party[i].partyType.name == "Drawee" || tw.local.idcContract.party[i].partyType.name == "Accountee") {
		tw.local.cifs.insertIntoList(tw.local.cifs.length, tw.local.idcContract.party[i].partyId);
		var pType = new tw.object.NameValuePair();
		pType.name = tw.local.idcContract.party[i].partyType.name;
		pType.value = tw.local.idcContract.party[i].partyType.value;
		tw.local.partyType.insertIntoList(tw.local.partyType.length, pType);
	}
	
}

tw.local.idcContract.facilities = new tw.object.listOf.creditFacilityInformation();
if(tw.local.SCQueryBCContractRes.Party_Limits != null){
	var mainFacilityIndex = 0;
	var subFacilityIndex = 0;
	var mainLinesIDsList = [];
	var linkedRefNo = "";
	var mainLineID = "";
	var mainLineIndex = 0;
	tw.local.idcContract.isLimitsTrackingRequired = true;
	for (var clIndex=0; clIndex<tw.local.SCQueryBCContractRes.Party_Limits.listLength; clIndex++) { // clIndex stands for Contracts Limits Index
		for (var afIndex=0; afIndex < tw.local.applicantAccounteeFacilities.listLength; afIndex++) { // afIndex stands for Applicant Facility Index
			mainLineID = tw.local.applicantAccounteeFacilities[afIndex].facilityID;
			for (var flIndex=0; flIndex<tw.local.applicantAccounteeFacilities[afIndex].facilityLines.length; flIndex++) { // flIndex stands for Facility Lines Index
				linkedRefNo = tw.local.applicantAccounteeFacilities[afIndex].facilityLines[flIndex].lineCode; //+ tw.local.applicantAccounteeFacilities[afIndex].facilityLines[flIndex].lineSerialNumber;
				if (tw.local.SCQueryBCContractRes.Party_Limits[clIndex].LINKEDREFNO == linkedRefNo) {
					mainLineIndex = mainLinesIDsList.indexOf(mainLineID);
					if (mainLineIndex == -1) {
						tw.local.idcContract.facilities[mainFacilityIndex] = tw.local.applicantAccounteeFacilities[afIndex];
						tw.local.idcContract.facilities[mainFacilityIndex].facilityLines[0] = tw.local.applicantAccounteeFacilities[afIndex].facilityLines[flIndex];
						tw.local.idcContract.facilities[mainFacilityIndex].facilityLines[0].facilityPercentageToBook = tw.local.SCQueryBCContractRes.Party_Limits[clIndex].LINKAGEPERC;	
						mainLinesIDsList[mainFacilityIndex]= mainLineID;
						mainFacilityIndex++;
					}
					else{
						subFacilityIndex = tw.local.idcContract.facilities[mainLineIndex].facilityLines.listLength;
						tw.local.idcContract.facilities[mainLineIndex].facilityLines[subFacilityIndex] = tw.local.applicantAccounteeFacilities[afIndex].facilityLines[flIndex];
						tw.local.idcContract.facilities[mainLineIndex].facilityLines[subFacilityIndex].facilityPercentageToBook = tw.local.SCQueryBCContractRes.Party_Limits[clIndex].LINKAGEPERC;	
					
					}
					
				}
			}
			
		}
	}
}

