tw.local.sqlStatements[j].sql="SELECT BILL_OF_LADING_REF, BILL_OF_LADING_DATE FROM BPM.IDC_REQUEST_BILLS WHERE IDC_REQUEST_ID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);
//------------------------------------- Get customer --------------------------------------------
j++;
i=0;
