tw.local.sqlStatements[j].sql="SELECT IMPORT_CARD_NUMBER FROM "+ tw.env.DBSchema +".IDC_CUSTOMER_INFORMATION WHERE IDC_REQUEST_ID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);
//------------------------------------- Get multi tenor --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT INSTALLMENT_DATE, INSTALLMENT_AMOUNT, TENOR_DAYS , MATURITY_DATE , OUTSTANDING_AMOUNT , LIQUIDATION_AMOUNT FROM BPM.IDC_REQUEST_MULTI_TENOR WHERE IDC_REQUEST_ID = ?;";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.results[0].rows[0].data[0]);
//------------------------------------- IS CUSTOMER SANCTIONS --------------------------------------------
j++;
i=0;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].sql="SELECT ID FROM "+ tw.env.DBSchema +".IDC_NBE_CUSTOMER_SANCTIONS where CIF_NUMBER = ?";
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
paramInit(tw.local.idcRequest.customerInformation.CIFNumber);
//------------------------------------- Get advance payment --------------------------------------------
//j++;
//i=0;
//tw.local.sqlStatements[j] = new tw.object.SQLStatement();
//tw.local.sqlStatements[j].sql="SELECT d.ID,d.REQUEST_NUMBER,BENEFICIARY_NAME, CURRENCY, DOCUMENT_AMOUNT, AMOUNT_PAYABLE_BY_NBE, ADVANCE_PAYMENT_OUTSTANDING_AMOUNT,i.INVOICE_NUMBER,a.AMOUNT_ALLOCATED_FOR_REQUEST, a.ALLOCATED_AMOUNT_IN_REQUEST_CURRENCY FROM BPM.IDC_REQUEST_DETAILS d join BPM.IDC_REQUEST_INVOICES i on i.IDC_REQUEST_ID = d.ID  join BPM.IDC_ADVANCED_PAYMENT_USED a on a.IDC_REQUEST_ID = d.ID where a.REFERRAL_REQUEST_NUMBER= ? ORDER BY d.ID;";
