scripts.script:
tw.local.type = tw.local.parentIDC.IDCRequestType.englishdescription;
if (tw.local.idcRequest.IDCRequestNature.englishdescription == ""+tw.epv.IDCRequestNature.New) {
	tw.local.fullPath = tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.BPM_Request_Number+" - "+tw.local.idcRequest.IDCRequestType.englishdescription+"/Issuance";
	tw.local.parentPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.BPM_Request_Number+" - "+tw.local.idcRequest.IDCRequestType.englishdescription;

}else if (tw.local.idcRequest.IDCRequestType.englishdescription == ""+tw.epv.IDCRequestTypes.idcPayment) {
	tw.local.fullPath = tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.idcRequest.ParentIDCRequestNumber+" - "+tw.local.type+"/Liquidation "+tw.local.BPM_Request_Number;
	tw.local.parentPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.idcRequest.ParentIDCRequestNumber+" - "+tw.local.type;

}else if (tw.local.idcRequest.IDCRequestType.englishdescription == ""+tw.epv.IDCRequestTypes.idcCompletion) {
	tw.local.fullPath = tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.idcRequest.ParentIDCRequestNumber+" - "+tw.local.type+"/Completion "+tw.local.BPM_Request_Number;
	tw.local.parentPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.idcRequest.ParentIDCRequestNumber+" - "+tw.local.type;

}

else if (tw.local.idcRequest.IDCRequestType.englishdescription == ""+tw.epv.IDCRequestTypes.idcWithdrawal) {
	tw.local.fullPath = tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.idcRequest.ParentIDCRequestNumber+" - "+tw.local.type+"/Withdrawal "+tw.local.BPM_Request_Number;
	tw.local.parentPath = tw.env.FILENET_ROOT_PATH+"/"+tw.local.idcRequest.customerInformation.CIFNumber+"/DC Inward/"+tw.local.idcRequest.ParentIDCRequestNumber+" - "+tw.local.type;

