if (tw.local.error != null && !!tw.local.error.errorText) {
	tw.local.errorMSG = tw.local.error.errorText;
}else if ( tw.system.error != null) {
	tw.local.errorMSG = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
	tw.local.error = new tw.object.AjaxError();
}else{
	tw.local.error = new tw.object.AjaxError();
}

tw.local.error.errorText = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name+"<br> Error Message : "+tw.local.errorMSG;
log.error("IDC PROCESS with ID "+tw.system.currentProcessInstanceID+" An Error Occured in Service Name : "+tw.system.serviceFlow.name+" with Error Message : "+tw.local.errorMSG);

tw.local.IDCRequest.DBID = tw.local.results[0].DBID;
tw.local.DBID = tw.local.results[0].DBID;
tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var j = 0
function paramInit (type,value) {
	tw.local.sqlStatements[j].parameters[tw.local.i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[tw.local.i].type = type;
	tw.local.sqlStatements[j].parameters[tw.local.i].value = value;
	tw.local.i= tw.local.i+1;
}
//-----------------------------invoice--------------------------------------------------

for (j=0; j<tw.local.IDCRequest.invoices.listLength; j++) {
	tw.local.sqlStatements[j] = new tw.object.SQLStatement();
	tw.local.sqlStatements[j].sql = "INSERT INTO "+ tw.env.DBSchema +".IDC_REQUEST_INVOICES (IDC_REQUEST_ID, INVOICE_NUMBER,INVOICE_DATE) VALUES (?,?,?) ;";
	
	tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
	tw.local.i = 0;
	
	paramInit("INTEGER",tw.local.IDCRequest.DBID);
	paramInit("VARCHAR",tw.local.IDCRequest.invoices[j].number);
	paramInit("DATE",tw.local.IDCRequest.invoices[j].date);
}

////-----------------------------customer---------------------------------------------------
//j+=1;
	tw.local.sqlStatements[j] = new tw.object.SQLStatement();
	tw.local.sqlStatements[j].sql = "INSERT INTO "+ tw.env.DBSchema +".IDC_CUSTOMER_INFORMATION (IDC_REQUEST_ID, CIF, CUSTOMER_NAME, CUSTOMER_SECTOR, CUSTOMER_TYPE, CUSTOMER_NUMBER_AT_CBE, FACILITY_TYPE_ID, COMMERCIAL_REGISTRATION_NUMBER, COMMERCIAL_REGISTRATION_OFFICE, TAX_CARD_NUMBER, IMPORT_CARD_NUMBER) VALUES (?,?,?,?,?,?,?,?,?,?,?) ;";
	
	tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
	tw.local.i = 0;
	
	paramInit("INTEGER",tw.local.IDCRequest.DBID);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.CIFNumber);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.customerName);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.customerSector);//can be update later <----------------------------------------------------
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.customerType);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.CBENumber);
	paramInit("INTEGER",tw.local.IDCRequest.customerInformation.facilityType.id);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.commercialRegistrationNumber);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.commercialRegistrationOffice);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.taxCardNumber);
	paramInit("VARCHAR",tw.local.IDCRequest.customerInformation.importCardNumber);
//-----------------------------bill-----------------------------------------------------
var n = 0;
j++;
for (; j<(tw.local.IDCRequest.billOfLading.listLength + tw.local.IDCRequest.invoices.listLength+1); j++) {
	tw.local.sqlStatements[j] = new tw.object.SQLStatement();
	tw.local.sqlStatements[j].sql = "INSERT INTO "+ tw.env.DBSchema +".IDC_REQUEST_BILLS (IDC_REQUEST_ID, BILL_OF_LADING_REF, BILL_OF_LADING_DATE) VALUES (?,?,?) ;";
	
	tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
	tw.local.i = 0;
	
	paramInit("INTEGER",tw.local.IDCRequest.DBID);
	paramInit("VARCHAR",tw.local.IDCRequest.billOfLading[n].number);
	paramInit("DATE",tw.local.IDCRequest.billOfLading[n].date);
	n+=1;
}
//-----------------------------------------facility-----------------------------------------------------------

if (tw.local.idcContract.facilities.listLength > 0) {
	for (var m_f_len=0; m_f_len < tw.local.idcContract.facilities.listLength; m_f_len++) {
		for (var s_f_len=0; s_f_len < tw.local.idcContract.facilities[m_f_len].facilityLines.listLength; s_f_len++) {
			tw.local.sqlStatements[j] = new tw.object.SQLStatement();
			tw.local.sqlStatements[j].sql = "INSERT INTO "+ tw.env.DBSchema +".IDC_FACILITY_DETAILS (IDC_REQUEST_ID, FACILITY_ID, CURRENCY, LINE_SERIAL, LINE_CODE, FACILITY_PERCENTAGE_TO_BOOK) VALUES (?,?,?,?,?,?) ;";
			
			tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
			tw.local.i = 0;
			paramInit("INTEGER",tw.local.IDCRequest.DBID);
			paramInit("VARCHAR",tw.local.idcContract.facilities[m_f_len].facilityID);
			paramInit("VARCHAR",tw.local.idcContract.facilities[m_f_len].facilityCurrency.value);
			paramInit("VARCHAR",tw.local.idcContract.facilities[m_f_len].facilityLines[s_f_len].lineSerialNumber);
			paramInit("VARCHAR",tw.local.idcContract.facilities[m_f_len].facilityLines[s_f_len].lineCode);
			paramInit("DECIMAL",tw.local.idcContract.facilities[m_f_len].facilityLines[s_f_len].facilityPercentageToBook);
			j++;
		}
	}
}
//----------------------------------------------------------------------multi tenor---------------------------------------------------------
var len = j;
n=0;
for (; j<(tw.local.IDCRequest.financialDetails.paymentTerms.listLength + len); j++) {
	if (tw.local.IDCRequest.financialDetails.paymentTerms[0].installmentAmount > 0 && tw.local.IDCRequest.financialDetails.paymentTerms[0].installmentAmount!= null && tw.local.IDCRequest.financialDetails.paymentTerms[0].installmentAmount != undefined) {
		tw.local.sqlStatements[j] = new tw.object.SQLStatement();
		tw.local.sqlStatements[j].sql = "INSERT INTO "+ tw.env.DBSchema +".IDC_REQUEST_MULTI_TENOR (IDC_REQUEST_ID, INSTALLMENT_DATE, INSTALLMENT_AMOUNT ,LIQUIDATION_AMOUNT) VALUES (?, ?, ? ,?) ;";
		
		tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
		tw.local.i = 0;
		
		paramInit("INTEGER",tw.local.IDCRequest.DBID);
		paramInit("VARCHAR",tw.local.IDCRequest.financialDetails.paymentTerms[n].installmentDate);
		paramInit("DATE",tw.local.IDCRequest.financialDetails.paymentTerms[n].installmentAmount);
		paramInit("DECIMAL",tw.local.IDCRequest.financialDetails.multiTenorDates[n].liquidationAmnt);
		n+=1;
	}
}

