tw.local.sqlStatements[0].parameters = new tw.object.listOf.SQLParameter();
tw.local.i = 0;
function paramInit (type,value) {
	tw.local.sqlStatements[0].parameters[tw.local.i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[0].parameters[tw.local.i].type = type;
	tw.local.sqlStatements[0].parameters[tw.local.i].value = value;
