scripts.script:
tw.local.isSuccessful = false;
if(tw.system.error)
	tw.local.errorMsg = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
else 
	tw.local.errorMsg = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name

/**----------------------------------------------------NOTES-----------------------------------------------------------------------**/

/**---------------------------------------------------------------------------------------------------------------------------------**/

tw.local.LiquidateBCCollectionReq = new tw.object.toolkit.NBEINTT.LiquidateBCCollectionReq();
tw.local.LiquidateBCCollectionReq.CONREFNO = tw.local.IdcRequest.FCContractNumber;
tw.local.LiquidateBCCollectionReq.LIQAMT = tw.local.IdcContract.liquidationSummary.liquidationAmt;
tw.local.LiquidateBCCollectionReq.VDATECR = tw.local.IdcContract.liquidationSummary.creditValueDate;
tw.local.LiquidateBCCollectionReq.DRVALDT = tw.local.IdcContract.liquidationSummary.debitValueDate;
tw.local.LiquidateBCCollectionReq.CUSTOMER_ID = tw.local.IdcRequest.customerInformation.CIFNumber;
tw.local.LiquidateBCCollectionReq.PRTYTYP = "DRAWEE";
tw.local.LiquidateBCCollectionReq.BranchNumber = tw.local.IdcRequest.appInfo.branch.value;
// tw.local.LiquidateBCCollectionReq.THECHGCCY = "";
// tw.local.LiquidateBCCollectionReq.THECHGAMT = "";

/**---------------------------------------------Charges And Settlements-------------------------------------------------**/
tw.local.LiquidateBCCollectionReq.Charges = new tw.object.toolkit.NBEINTT.Charges_11();
tw.local.LiquidateBCCollectionReq.Charges.CONREFNO = tw.local.IdcRequest.FCContractNumber;

tw.local.LiquidateBCCollectionReq.Settlements = new tw.object.toolkit.NBEINTT.Settlements_16();
tw.local.LiquidateBCCollectionReq.Settlements.CONREFNO = tw.local.IdcRequest.FCContractNumber;
// tw.local.LiquidateBCCollectionReq.Settlements.LATEVNSEQNO = "";
tw.local.LiquidateBCCollectionReq.Settlements.Contract_Settlement = new tw.object.listOf.toolkit.NBEINTT.Contract_Settlement_11();

/**----------------------------------------------Charges---------------------------------------------------------------**/
if (tw.local.IdcContract.commissionsAndChargesLiq && tw.local.IdcContract.commissionsAndChargesLiq.length > 0) {
	tw.local.LiquidateBCCollectionReq.Charges.Charge_Application = new tw.object.listOf.toolkit.NBEINTT.Charge_Application_8();

	for (var i = 0; i < tw.local.IdcContract.commissionsAndChargesLiq.length; i++) {
		var component = tw.local.IdcContract.commissionsAndChargesLiq[i].component;
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i] = new tw.object.toolkit.NBEINTT.Charge_Application_8();
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i].COMPNT = component;
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i].CHRGAMT = tw.local.IdcContract.commissionsAndChargesLiq[i].chargeAmount;
		tw.local.LiquidateBCCollectionReq.Charges.Charge_Application[i].WAIVER = tw.local.IdcContract.commissionsAndChargesLiq[i].waiver ? "Y" : "N";

		/**----------------------------------------------------------------------------------------------------------**/
		if (!tw.local.IdcContract.commissionsAndChargesLiq[i].waiver && tw.local.IdcContract.commissionsAndChargesLiq[i].debitedAccount) {
			var glAccountNo = tw.local.IdcContract.commissionsAndChargesLiq[i].debitedAccount.GLAccountNumber;
			var accountNumber = tw.local.IdcContract.commissionsAndChargesLiq[i].debitedAccount.accountNumber;
			var acc = glAccountNo || accountNumber;
			var accountBranchCode = tw.local.IdcContract.commissionsAndChargesLiq[i].debitedAccount.accountBranchCode;
			var accountCurrency = tw.local.IdcContract.commissionsAndChargesLiq[i].debitedAccount.accountCurrency.code;
			addContractSettlement(component, accountBranchCode, acc, accountCurrency);
		}
	}
}
/**---------------------------------------------Liquidation Settlements-------------------------------------------------**/
var componentLiq = "BILL_LIQ_AMT";
if (tw.local.IdcContract.settlementAccounts && tw.local.IdcContract.settlementAccounts.length > 0) {
	for(var i = 0; i < tw.local.IdcContract.settlementAccounts.length; i++) {
		if (tw.local.IdcContract.settlementAccounts[i].debitedAccount) {
			var glAccountNo = tw.local.IdcContract.settlementAccounts[i].debitedAccount.GLAccountNumber;
			var accountNumber = tw.local.IdcContract.settlementAccounts[i].debitedAccount.accountNumber;
			var acc = glAccountNo || accountNumber;
			var accountBranchCode = tw.local.IdcContract.settlementAccounts[i].debitedAccount.accountBranchCode;
			var accountCurrency = tw.local.IdcContract.settlementAccounts[i].debitedAccount.currency.value;
			addContractSettlement(componentLiq, accountBranchCode, acc, accountCurrency);
		}
	}
}

