/**----------------------------------------------------NOTES-----------------------------------------------------------------------**/
// Advices is assumed and needs verification !!
// Accountee is skipped
// REMITTING BANK - DRAWER - CASE IN NEED - DRAWEE
// Interest details not added
// Collateral Details not added
/**---------------------------------------------------------------------------------------------------------------------------------**/

// Constants for Party Types
const PARTY_TYPES = {
    REMITTING_BANK: "REMITTING BANK",
    DRAWER: "DRAWER",
    DRAWEE: "DRAWEE",
    CASE_IN_NEED: "CASE IN NEED",
    ACCOUNTEE: "ACCOUNTEE"
};

// Constants for Default Values
const DEFAULT_VALUES = {
	CREATE_SN: "1",
	YES: "Y",
	NO: "N",
	SWIFT: "SWIFT"
};
/**---------------------------------------------------------------------------------------------------------------------------------**/
tw.local.Contract_Details_IO = new tw.object.toolkit.NBEINTT.Contract_Details_IO_3();
tw.local.Contract_Details_IO.CONREFNO = tw.local.IDCRequest.FCContractNumber;
tw.local.Contract_Details_IO.EXTREFNO = tw.local.IDCRequest.FCContractNumber;
tw.local.Contract_Details_IO.USEREFNO = tw.local.IDCContract.userReference;
tw.local.Contract_Details_IO.OPERATION = tw.local.IDCRequest.operationType.value;
var idcStage = tw.local.IDCContract.IDCRequestStage;
var BillStage = idcStage == tw.epv.IDCstage.fiinal + "" ? tw.epv.IDCstage.fin + "" : tw.epv.IDCstage.ini + "";
tw.local.Contract_Details_IO.STAG = BillStage;
tw.local.Contract_Details_IO.AMOUNT = String(tw.local.IDCRequest.financialDetails.documentAmount);
tw.local.Contract_Details_IO.VALDT = formatDate(tw.local.IDCContract.transactionValueDate);
tw.local.Contract_Details_IO.MATDT = formatDate(tw.local.IDCContract.transactionMaturityDate);
tw.local.Contract_Details_IO.TENOR_DAYS = String(tw.local.IDCContract.transactionTenorDays);
tw.local.Contract_Details_IO.TRANSITDAYS = String(tw.local.IDCContract.transactionTransitDays);
tw.local.Contract_Details_IO.BASDT = formatDate(tw.local.IDCContract.transactionBaseDate);
tw.local.Contract_Details_IO.FROMDATE = formatDate(tw.local.IDCContract.interestFromDate);
tw.local.Contract_Details_IO.TODATE = formatDate(tw.local.IDCContract.interestToDate);
//From Query <-----------
tw.local.Contract_Details_IO.USRDEFSTATS = tw.local.BC_Contract.USRDEFSTATS || "";
//---------------------->
tw.local.Contract_Details_IO.BRANCH = tw.local.IDCRequest.financialDetails.executionHub.code;
tw.local.Contract_Details_IO.PRODCD = tw.local.IDCContract.IDCProduct.code;
tw.local.Contract_Details_IO.CURRENCY = tw.local.IDCRequest.financialDetails.documentCurrency.code;
tw.local.Contract_Details_IO.OUTSTAMT = String(tw.local.IDCContract.outstandingAmount);
tw.local.Contract_Details_IO.CUSTOMER_ID = tw.local.IDCRequest.customerInformation.CIFNumber;
tw.local.Contract_Details_IO.CCY = tw.local.IDCRequest.financialDetails.documentCurrency.code;
tw.local.Contract_Details_IO.COLLCCY = tw.local.IDCContract.collateralCurrency.code;
tw.local.Contract_Details_IO.REBATE_AMT = String(tw.local.IDCRequest.financialDetails.contractRebateAmnt || 0);
//tw.local.Contract_Details_IO.TFR_COLL_AMT = String(tw.local.IDCContract.collateralAmount);

/**---------------------------------------------Parties-------------------------------------------------------**/
tw.local.Contract_Details_IO.Contract_Parties = new tw.object.listOf.toolkit.NBEINTT.Contract_Parties_11();

if (tw.local.IDCContract.party && tw.local.IDCContract.party.length > 0) {
	for (var i = 0; i < tw.local.IDCContract.party.length; i++) {
		if (tw.local.IDCContract.party[i].partyType.value.toLowerCase() == PARTY_TYPES.ACCOUNTEE.toLocaleLowerCase()) continue;
		tw.local.Contract_Details_IO.Contract_Parties[i] = new tw.object.toolkit.NBEINTT.Contract_Parties_11();
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTLANG = tw.local.IDCContract.party[i].language;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTCTRCOD = tw.local.IDCContract.party[i].country;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTREFNO = tw.local.IDCContract.party[i].reference;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTNAM = tw.local.IDCContract.party[i].name;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTADD1 = tw.local.IDCContract.party[i].address1;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTADD2 = tw.local.IDCContract.party[i].address2;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTADD3 = tw.local.IDCContract.party[i].address3;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTID = tw.local.IDCContract.party[i].partyId;
		tw.local.Contract_Details_IO.Contract_Parties[i].PARTTYP = tw.local.IDCContract.party[i].partyType.value.toUpperCase();

		if (tw.local.Contract_Details_IO.Contract_Parties[i].PARTTYP.trim().toLowerCase() == PARTY_TYPES.REMITTING_BANK.toLocaleLowerCase()) {
			tw.local.Contract_Details_IO.Contract_Parties[i].Party_Addr = new tw.object.listOf.toolkit.NBEINTT.Party_Addr_3();
			tw.local.Contract_Details_IO.Contract_Parties[i].Party_Addr[0] = new tw.object.toolkit.NBEINTT.Party_Addr_3();
			tw.local.Contract_Details_IO.Contract_Parties[i].Party_Addr[0].MEDIA = tw.local.IDCContract.party[i].media;
			tw.local.Contract_Details_IO.Contract_Parties[i].Party_Addr[0].ADDR = tw.local.IDCContract.party[i].address;
		}
	}
}

/**---------------------------------------------Charges and Settlements-------------------------------------------------**/
tw.local.Contract_Details_IO.Charges = new tw.object.toolkit.NBEINTT.Charges_28();
tw.local.Contract_Details_IO.Settlements = new tw.object.toolkit.NBEINTT.Settlements_28();
tw.local.Contract_Details_IO.Settlements.Contract_Settlement = new tw.object.listOf.toolkit.NBEINTT.Contract_Settlement_24();
tw.local.Contract_Details_IO.Charges.CONREFNO = tw.local.IDCRequest.FCContractNumber;
tw.local.Contract_Details_IO.Settlements.CONREFNO = tw.local.IDCRequest.FCContractNumber;

if (tw.local.IDCContract.commissionsAndCharges && tw.local.IDCContract.commissionsAndCharges.length > 0) {
	tw.local.Contract_Details_IO.Charges.Charge_Application = new tw.object.listOf.toolkit.NBEINTT.Charge_Application_16();
	tw.local.Contract_Details_IO.Charges.Charge_Association = new tw.object.listOf.toolkit.NBEINTT.Charge_Association_19();
	for (var i = 0; i < tw.local.IDCContract.commissionsAndCharges.length; i++) {
		tw.local.Contract_Details_IO.Charges.Charge_Application[i] = new tw.object.toolkit.NBEINTT.Charge_Application_16();
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].COMPNT = tw.local.IDCContract.commissionsAndCharges[i].component;
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].CHRGAMT = String(tw.local.IDCContract.commissionsAndCharges[i].chargeAmount);
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].WAIVER = tw.local.IDCContract.commissionsAndCharges[i].waiver ? DEFAULT_VALUES.YES : DEFAULT_VALUES.NO;
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].CREATESN = DEFAULT_VALUES.CREATE_SN;
		tw.local.Contract_Details_IO.Charges.Charge_Application[i].CHRGCCY = tw.local.IDCContract.commissionsAndCharges[i].defaultCurrency.code;

		tw.local.Contract_Details_IO.Charges.Charge_Association[i] = new tw.object.toolkit.NBEINTT.Charge_Association_19();
		tw.local.Contract_Details_IO.Charges.Charge_Association[i].COMPNT = tw.local.IDCContract.commissionsAndCharges[i].component;
		tw.local.Contract_Details_IO.Charges.Charge_Association[i].CREATESN = DEFAULT_VALUES.CREATE_SN;
		tw.local.Contract_Details_IO.Charges.Charge_Association[i].WAIVER = tw.local.IDCContract.commissionsAndCharges[i].waiver ? DEFAULT_VALUES.YES : DEFAULT_VALUES.NO;

		if (!tw.local.IDCContract.commissionsAndCharges[i].waiver && tw.local.IDCContract.commissionsAndCharges[i].debitedAccount && tw.local.IDCContract.commissionsAndCharges[i].debitedAmount) {

			var cpmnt = tw.local.IDCContract.commissionsAndCharges[i].component;
			var ccy = tw.local.IDCContract.commissionsAndCharges[i].defaultCurrency.code;
			var branch = String(tw.local.IDCContract.commissionsAndCharges[i].debitedAccount.accountBranchCode);
			var acc = tw.local.IDCContract.commissionsAndCharges[i].debitedAccount.GLAccountNumber || tw.local.IDCContract.commissionsAndCharges[i].debitedAccount.accountNumber;
			var exRate = String(tw.local.IDCContract.commissionsAndCharges[i].debitedAmount.standardExchangeRate);
			var nExRate = String(tw.local.IDCContract.commissionsAndCharges[i].debitedAmount.negotiatedExchangeRate);

			addContractSettlement(cpmnt, branch, acc, ccy, exRate, nExRate);
			
		}
	}
}

/**------------------------------------------------Contract_Multitnr----------------------------------------------------**/
if (tw.local.IDCRequest.financialDetails.multiTenorDates.length > 0) {
	tw.local.Contract_Details_IO.Contract_Multitnr = new tw.object.listOf.toolkit.NBEINTT.Contract_Multitnr_2();
	for (var i = 0; i < tw.local.IDCRequest.financialDetails.multiTenorDates.length; i++) {
		tw.local.Contract_Details_IO.Contract_Multitnr[i] = new tw.object.toolkit.NBEINTT.Contract_Multitnr_2();
		tw.local.Contract_Details_IO.Contract_Multitnr[i].SERIALNUM = String(i);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].BASDATE = formatDate(tw.local.IDCRequest.financialDetails.multiTenorDates[i].instalmentBaseDate);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].VALUDATE = formatDate(tw.local.IDCContract.transactionValueDate);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].TNOR = String(tw.local.IDCRequest.financialDetails.multiTenorDates[i].instalmentTenorDays);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].MATDAT = formatDate(tw.local.IDCRequest.financialDetails.multiTenorDates[i].instalmentMaturityDate);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].BILLAMNT = String(tw.local.IDCRequest.financialDetails.multiTenorDates[i].amount);
		tw.local.Contract_Details_IO.Contract_Multitnr[i].REBATAMT = String(tw.local.IDCRequest.financialDetails.multiTenorDates[i].splitRebateAmnt);
	}
}

/**---------------------------------------------Document_Details---------------------------------------------------------------------**/
if (tw.local.BC_Contract && tw.local.BC_Contract.Document_Details && tw.local.BC_Contract.Document_Details.listLength > 0) {
	tw.local.Contract_Details_IO.Document_Details = new tw.object.listOf.toolkit.NBEINTT.Document_Details_11();
	for (var i = 0; i < tw.local.BC_Contract.Document_Details.listLength; i++) {
		tw.local.Contract_Details_IO.Document_Details[i] = new tw.object.toolkit.NBEINTT.Document_Details_11();
		tw.local.Contract_Details_IO.Document_Details[i].DOCCD = tw.local.BC_Contract.Document_Details[i].DocCode;
		tw.local.Contract_Details_IO.Document_Details[i].DESC = tw.local.BC_Contract.Document_Details[i].DocDesc;
		// tw.local.Contract_Details_IO.Document_Details[0].FRSTMAILCOP = "";
		// tw.local.Contract_Details_IO.Document_Details[0].FRSTMAILORG = "";
	}
}

/**------------------------------------------------Adice----------------------------------------------------**/
tw.local.Contract_Details_IO.Adice = new tw.object.toolkit.NBEINTT.Adice_2();
if (tw.local.IDCContract.advices && tw.local.IDCContract.advices.listLength > 0) {
	tw.local.Contract_Details_IO.Adice.ADV_CODE = tw.local.IDCContract.advices[0].messageType;
	tw.local.Contract_Details_IO.Adice.SUPRESS = tw.local.IDCContract.advices[0].suppressed ? DEFAULT_VALUES.YES : DEFAULT_VALUES.NO;
	// tw.local.Contract_Details_IO.Adice.PRTY = "";
	tw.local.Contract_Details_IO.Adice.MEDIUM = DEFAULT_VALUES.SWIFT;
	tw.local.Contract_Details_IO.Adice.Fft = new tw.object.listOf.toolkit.NBEINTT.Fft_2();
	tw.local.Contract_Details_IO.Adice.Fft[0] = new tw.object.toolkit.NBEINTT.Fft_2();
	tw.local.Contract_Details_IO.Adice.Fft[0].FFT_CODE = tw.local.IDCContract.advices[0].adviceCode;
	// combine all advicelines into one txt
	var combinedText = tw.local.IDCContract.advices[0].advicelines.propertyValues.join(" ").trim() || "";
	tw.local.Contract_Details_IO.Adice.Fft[0].FFTTXT = combinedText;
