scripts.script:
// mail to
var instanceId = tw.local.RecallDetails.requestInfo.instanceID || "";
if(instanceId != ""){

var tasksList = tw.system.findProcessInstanceByID(instanceId).tasks;
var toList = [];
var systemUser =  tw.env.SYSTEM_USER;
var atr = "Task Email Address";

// map a new lis of user names from the tasklist
var userNameList = tasksList.map(function (task) {
      return task.assignedTo.toString();
});

// filter out the system user and the duplicates from the user name list
var uniqueUserNames = userNameList.filter(function (userName, index, self) {
	return userName && userName !== systemUser && self.indexOf(userName) === index;
});

if (uniqueUserNames && uniqueUserNames.length > 0) {
	uniqueUserNames.forEach(function (userName) {
		if (userName && tw.system.org.findUserByName(userName)) {
			var email = tw.system.org.findUserByName(userName).attributes[atr] || "";
			if (email && email !== "") {
				toList.push(email);
			}
		}
	});
}

tw.local.mailTo = "";
if (toList.length > 0) { 
	tw.local.mailTo = toList.join(",");
}

// mail body
var requestType = tw.local.RecallDetails.requestInfo.requestType;
var requestNo = tw.local.RecallDetails.requestNum;
var customerName = tw.local.RecallDetails.customerInfo.customerName;
var cif = tw.local.RecallDetails.customerInfo.CIFNumber;
var recaller = tw.system.user.fullName || "";
var requestDate = tw.local.RecallDetails.requestInfo.requestDate;
var documentAmount = tw.local.RecallDetails.documentAmnt;
var currency = tw.local.RecallDetails.documentCcry;
var status = tw.local.RecallDetails.requestInfo.status;
var subStatus = tw.local.RecallDetails.requestInfo.subStatus;
var recallReason = tw.local.RecallDetails.recallReason;

tw.local.subject = "Recalling " + requestType + " " + requestNo + " for Customer " + customerName;

tw.local.msgBody =
	'<html dir="ltr" lang="en">' +
	"<p>Dear Sir / Madam,</p>" +
	"<p>Kindly be informed that " +
	recaller +
	" would like to recall this request.</p>" +
	"<ul>" +
	"<li>Request Number: " +
	requestNo +
	"</li>" +
	"<li>Request Type: " +
	requestType +
	"</li>" +
	"<li>Customer: " +
	cif +
	" [" +
	customerName +
	"]</li>" +
	"<li>Request Date: " +
	requestDate +
	"</li>" +
	"<li>Document Amount: " +
	currency +
	" " +
	documentAmount +
	"</li>" +
	"<li>Current Status: " +
	status +
	" / " +
	subStatus +
	"</li>" +
	"<li>Recall Reason: " +
	recallReason +
	"</li>" +
	"</ul>" +
	"<p>Please do not reply to this message. This is an automatically generated email.</p>";

// Add Arabic version
tw.local.msgBody +=
	"<br><br>" +
	'<p dir="rtl" lang="ar">السيد / السيدة،</p>' +
	'<p dir="rtl" lang="ar">نحيط علمكم بأن ' +
	recaller +
	" يرغب في سحب هذا الطلب.</p>" +
	'<p dir="rtl" lang="ar">رقم الطلب: ' +
	requestNo +
	"<br>" +
	"نوع الطلب: " +
	requestType +
	"<br>" +
	"العميل: " +
	cif +
	" [" +
	customerName +
	"]<br>" +
	"تاريخ الطلب: " +
	requestDate +
	"<br>" +
	"مبلغ المستند: " +
	documentAmount +
	" " +
	currency +
	"<br>" +
	"الحالة الحالية: " +
	status +
	" / " +
	subStatus +
	"<br>" +
	"سبب السحب: " +
	recallReason +
	"</p>" +
	'<p dir="rtl" lang="ar">برجاء عدم الرد على هذه الرسالة. هذا بريد إلكتروني يتم إنشاؤه تلقائيًا.</p>';
}

//var str = "eslam alaa mohamed";
//tw.local.result = str.substring(8);

tw.local.variable2=new tw.object.TaskListProperties();
tw.local.variable2.interactionFilter="ASSESS_AVAILABLE";
tw.local.variable1=tw.system.retrieveTaskList(tw.local.variable2, -1, 0, tw.system.user_timeZone);

tw.local.output1 = tw.system.currentTask.processActivityName

tw.local.Seperated = new tw.object.listOf.String();
tw.local.Seperated = tw.local.data.split("/");
tw.local.requestID = tw.local.Seperated[0].split("-")[0];
tw.local.tmpAdvancePayment = new tw.object.UsedAdvancePayment();
tw.local.tmpAdvancePayment.AllocatedAmountinRequestCurrency = tw.local.Seperated[1];
tw.local.tmpAdvancePayment.AmountAllocated = tw.local.Seperated[2];
tw.local.tmpAdvancePayment.DBID = tw.local.Seperated[3];
tw.local.instanceID = tw.local.Seperated[4];

tw.local.sqlStatements = new tw.object.listOf.SQLStatement();
var i = 0;
var j = 0;
function paramInit (type,value) {
	tw.local.sqlStatements[j].parameters[i] = new tw.object.SQLParameter();
	tw.local.sqlStatements[j].parameters[i].type = type;
	tw.local.sqlStatements[j].parameters[i].value = value;
	i= i+1;
}
//---------------------------------------------UPDATE Amount---------------------------------
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStatements[j].sql = "UPDATE "+ tw.env.DBSchema +".IDC_ADVANCED_PAYMENT_USED SET AMOUNT_ALLOCATED_FOR_REQUEST= ? ,ALLOCATED_AMOUNT_IN_REQUEST_CURRENCY = ? WHERE "+ tw.env.DBSchema +".IDC_ADVANCED_PAYMENT_USED.IDC_REQUEST_ID = ? AND "+ tw.env.DBSchema +".IDC_ADVANCED_PAYMENT_USED.REFERRAL_REQUEST_NUMBER like ?;";

paramInit ("DECIMAL",tw.local.tmpAdvancePayment.AmountAllocated);
paramInit ("DECIMAL",tw.local.tmpAdvancePayment.AllocatedAmountinRequestCurrency);
paramInit ("INTEGER",tw.local.tmpAdvancePayment.DBID);
paramInit ("VARCHAR",tw.local.requestID+"%");
//----------------------------------------------UPDATE Advance Payment----------------------------------
i=0;
j++;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStatements[j].sql = "update "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS set  ADVANCE_PAYMENT_OUTSTANDING_AMOUNT = ( (select min( AMOUNT_PAYABLE_BY_NBE) from "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS where ID= ?) - COALESCE((select sum(AMOUNT_ALLOCATED_FOR_REQUEST) from "+ tw.env.DBSchema +".IDC_ADVANCED_PAYMENT_USED where IDC_REQUEST_ID=? ),0)) where ID=?";

paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);
paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);
paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);
//-------------------------------------------Select-----------------------------------
i=0;
j++;
tw.local.sqlStatements[j] = new tw.object.SQLStatement();
tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();
tw.local.sqlStatements[j].sql = "SELECT ADVANCE_PAYMENT_OUTSTANDING_AMOUNT FROM "+ tw.env.DBSchema +".IDC_REQUEST_DETAILS WHERE ID=?;";

paramInit ("VARCHAR",tw.local.tmpAdvancePayment.DBID);

if (tw.local.error != null && !!tw.local.error.errorText) {
	tw.local.errorMSG = tw.local.error.errorText;
}else if ( tw.system.error != null) {
	tw.local.errorMSG = String(tw.system.error.getAttribute("type")) +","+ String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText());
	tw.local.error = new tw.object.AjaxError();
}else{
	tw.local.error = new tw.object.AjaxError();
}

tw.local.error.errorText = "Error Occured<br> Service Name : "+tw.system.serviceFlow.name+"<br> Error Message : "+tw.local.errorMSG;
log.error("IDC PROCESS with ID "+tw.local.instanceID+" An Error Occured in Service Name : "+tw.system.serviceFlow.name+" with Error Message : "+tw.local.errorMSG);

