}else{
	for (var i=tw.local.facilities.listLength-1; i>=0; i--) {
		tw.local.isfound = false;
		for (var j=0; j<tw.local.facilityCodes.listLength; j++) {
			if (tw.local.facilities[i].facilityCode == tw.local.facilityCodes[j].value) {
